#include <sstream>
#include <stdexcept>

#include "translator.hpp"

namespace
{

const char* const TAB = "    ";
const char* const AUTOGENERATED_FILE_MESSAGE =
    "// This file is generated from docs/smbdis.asm by codegen.\n"
    "// Do not edit directly: build the 'regenerate' target instead.\n"
    "//\n";
const char* const LINE_SEPARATOR_COMMENT = "//------------------------------------------------------------------------\n";

// Address where constant data starts in the emulated address space.
//
const int DATA_STORAGE_ADDRESS = 0x8000;

// C++ templates for instructions. Placeholders:
//   {o} - the operand, read through memory unless it is immediate
//   {e} - the operand expression itself (an address or branch target)
//   {t} - the target of a shift/rotate: the operand, or the accumulator if there is none
//
const char* instructionTemplate(Opcode opcode)
{
    switch (opcode)
    {
    case Opcode::LDA: return "a = {o};";
    case Opcode::LDX: return "x = {o};";
    case Opcode::LDY: return "y = {o};";
    case Opcode::STA: return "writeData({e}, a);";
    case Opcode::STX: return "writeData({e}, x);";
    case Opcode::STY: return "writeData({e}, y);";
    case Opcode::TAX: return "x = a;";
    case Opcode::TAY: return "y = a;";
    case Opcode::TXA: return "a = x;";
    case Opcode::TYA: return "a = y;";
    case Opcode::TSX: return "x = s;";
    case Opcode::TXS: return "s = x;";
    case Opcode::PHA: return "pha();";
    case Opcode::PLA: return "pla();";
    case Opcode::AND: return "a &= {o};";
    case Opcode::EOR: return "a ^= {o};";
    case Opcode::ORA: return "a |= {o};";
    case Opcode::BIT: return "bit({o});";
    case Opcode::ADC: return "a += {o};";
    case Opcode::SBC: return "a -= {o};";
    case Opcode::CMP: return "compare(a, {o});";
    case Opcode::CPX: return "compare(x, {o});";
    case Opcode::CPY: return "compare(y, {o});";
    case Opcode::INC: return "++{o};";
    case Opcode::INX: return "++x;";
    case Opcode::INY: return "++y;";
    case Opcode::DEC: return "--{o};";
    case Opcode::DEX: return "--x;";
    case Opcode::DEY: return "--y;";
    case Opcode::ASL: return "{t} <<= 1;";
    case Opcode::LSR: return "{t} >>= 1;";
    case Opcode::ROL: return "{t}.rol();";
    case Opcode::ROR: return "{t}.ror();";
    case Opcode::RTS: return "goto Return;";
    case Opcode::RTI: return "return;";
    case Opcode::BCC: return "if (!c)\n        goto {e};";
    case Opcode::BCS: return "if (c)\n        goto {e};";
    case Opcode::BEQ: return "if (z)\n        goto {e};";
    case Opcode::BNE: return "if (!z)\n        goto {e};";
    case Opcode::BMI: return "if (n)\n        goto {e};";
    case Opcode::BPL: return "if (!n)\n        goto {e};";
    case Opcode::CLC: return "c = 0;";
    case Opcode::SEC: return "c = 1;";
    case Opcode::CLD: return "/* cld */";
    case Opcode::SEI: return "/* sei */";
    case Opcode::NOP: return "; // nop";
    default:          return nullptr; // Not used by Super Mario Bros.
    }
}

void replaceAll(std::string& text, const std::string& from, const std::string& to)
{
    for (std::size_t pos = text.find(from); pos != std::string::npos; pos = text.find(from, pos + to.size()))
    {
        text.replace(pos, from.size(), to);
    }
}

class Translator
{
public:
    explicit Translator(Program& program) :
        program(program)
    {
    }

    GeneratedSources run()
    {
        GeneratedSources sources;
        sources.constants = generateConstants();
        generateData(sources.data, sources.dataAddresses);
        sources.code = generateCode();
        return sources;
    }

private:
    Program& program;
    int returnLabelCount = 0;
    int skipLabelCount = 0;

    // ".db $2c" hides the next instruction behind the operand of a BIT
    // instruction, so it translates into a jump over that instruction.
    // The hidden instruction may start the next label.
    //
    bool skipNextInstruction = false;

    // Comments are claimed once, by the first construct that asks for its line.
    //
    std::string takeComment(int line)
    {
        auto it = program.comments.find(line);
        if (line == 0 || it == program.comments.end())
        {
            return "";
        }
        std::string comment = " // " + it->second;
        program.comments.erase(it);
        return comment;
    }

    std::string generateConstants()
    {
        std::ostringstream out;
        out << AUTOGENERATED_FILE_MESSAGE <<
            "#ifndef SMBCONSTANTS_HPP\n" <<
            "#define SMBCONSTANTS_HPP\n\n" <<
            "#include \"SMBDataPointers.hpp\"\n\n";

        for (const Decl* decl : program.decls)
        {
            out << "constexpr uint16_t " << decl->name << " = " << translateExpression(decl->value) << ";" << takeComment(decl->line) << "\n";
        }

        out << "\n#endif // SMBCONSTANTS_HPP\n";
        return out.str();
    }

    void generateData(std::string& data, std::string& dataAddresses)
    {
        std::ostringstream addresses; // Address of each data label
        std::ostringstream loading;   // Body of loadConstantData()

        int address = DATA_STORAGE_ADDRESS;
        for (const Label* label : program.labels)
        {
            if (label->type == LabelType::Code)
            {
                continue;
            }

            addresses << "constexpr uint16_t " << label->name << " = 0x" << std::hex << address << std::dec << ";" <<
                (label->type == LabelType::Alias ? " // alias" : "") << "\n";

            // Aliases share the address of the next label, so there is nothing to store for them
            //
            if (label->type == LabelType::Data)
            {
                address += generateDataTable(loading, *label);
            }
        }

        dataAddresses = std::string(AUTOGENERATED_FILE_MESSAGE) +
            "#ifndef SMBDATAPOINTERS_HPP\n" +
            "#define SMBDATAPOINTERS_HPP\n\n" +
            "#include <cstdint>\n\n" +
            "// Addresses of the constant data tables in the emulated address space\n" +
            "//\n" +
            addresses.str() + "\n" +
            "#endif // SMBDATAPOINTERS_HPP\n";

        data = std::string(AUTOGENERATED_FILE_MESSAGE) +
            "#include \"SMB.hpp\"\n\n" +
            "void SMBEngine::loadConstantData()\n{\n" +
            loading.str() +
            "}\n";
    }

    // Emit the array for one data label. Returns the number of bytes it occupies.
    //
    int generateDataTable(std::ostringstream& out, const Label& label)
    {
        const std::string& name = label.name;
        out << TAB << "// " << name << "\n" << TAB << "//\n" << TAB << "static constexpr uint8_t " << name << "_data[] = {";

        int byteCount = 0;
        const auto& statements = label.statements;
        for (std::size_t i = 0; i < statements.size(); i++)
        {
            const Statement* statement = statements[i];
            if (statement->kind != Statement::Kind::Bytes)
            {
                throw std::runtime_error("unexpected instruction in data label " + name);
            }

            out << "\n" << TAB << TAB;
            for (std::size_t j = 0; j < statement->data.size(); j++)
            {
                out << (j > 0 ? ", " : "") << translateExpression(statement->data[j]);
            }
            byteCount += static_cast<int>(statement->data.size());

            if (i + 1 < statements.size())
            {
                // Word data only follows bytes at the very end of the disassembly
                // (the interrupt vectors), which are not needed
                //
                if (statements[i + 1]->kind == Statement::Kind::Words)
                {
                    break;
                }
                out << ",";
            }
            out << takeComment(statement->line);
        }

        out << "\n" << TAB << "};\n";
        out << TAB << "writeData(" << name << ", " << name << "_data, sizeof(" << name << "_data));\n\n";
        return byteCount;
    }

    std::string generateCode()
    {
        std::ostringstream out;
        out << AUTOGENERATED_FILE_MESSAGE <<
            "#include \"SMB.hpp\"\n\n" <<
            "void SMBEngine::code(int mode)\n" <<
            "{\n" <<
            TAB << "switch (mode)\n" <<
            TAB << "{\n" <<
            TAB << "case 0:\n" <<
            TAB << TAB << "loadConstantData();\n" <<
            TAB << TAB << "goto Start;\n" <<
            TAB << "case 1:\n" <<
            TAB << TAB << "goto NonMaskableInterrupt;\n" <<
            TAB << "}\n\n";

        for (const Label* label : program.labels)
        {
            if (label->type != LabelType::Code)
            {
                continue;
            }

            out << "\n" << label->name << ":" << takeComment(label->line) << "\n";

            const auto& statements = label->statements;
            for (std::size_t i = 0; i < statements.size(); i++)
            {
                const Statement* statement = statements[i];
                if (statement->kind == Statement::Kind::Instruction)
                {
                    out << TAB << translateInstruction(*label, i) << takeComment(statement->line);
                    if (statement->opcode == Opcode::RTS)
                    {
                        out << "\n\n" << LINE_SEPARATOR_COMMENT;
                    }
                    else
                    {
                        out << "\n";
                    }

                    if (skipNextInstruction)
                    {
                        out << "Skip_" << skipLabelCount++ << ":\n";
                        skipNextInstruction = false;
                    }
                }
                else if (statement->kind == Statement::Kind::Bytes && statement->data.front()->text == "$2c")
                {
                    skipNextInstruction = true;
                    out << TAB << "goto Skip_" << skipLabelCount << ";\n";
                }
            }
        }

        // RTS is emulated with a jump table of every JSR return point
        //
        out << "// Return handler\n" <<
            "// This emulates the RTS instruction using a generated jump table\n" <<
            "//\n" <<
            "Return:\n" <<
            TAB << "switch (popReturnIndex())\n" <<
            TAB << "{\n";
        for (int i = 0; i < returnLabelCount; i++)
        {
            out << TAB << "case " << i << ":\n" << TAB << TAB << "goto Return_" << i << ";\n";
        }
        out << TAB << "}\n}\n";

        return out.str();
    }

    std::string translateInstruction(const Label& label, std::size_t index)
    {
        const Statement& instruction = *label.statements[index];
        const Expr* operand = instruction.operand;

        switch (instruction.opcode)
        {
        case Opcode::JMP:
            // Indirect jumps only occur in JumpEngine, which is replaced by a switch at each call site
            //
            if (operand->type != ExprType::Name)
            {
                return "";
            }
            return operand->text == "EndlessLoop" ? "return;" : "goto " + operand->text + ";";

        case Opcode::JSR:
            if (operand->text == "JumpEngine")
            {
                return translateJumpTable(label, index);
            }
            return "JSR(" + operand->text + ", " + std::to_string(returnLabelCount++) + ");";

        default:
            break;
        }

        const char* format = instructionTemplate(instruction.opcode);
        if (format == nullptr)
        {
            throw std::runtime_error("unsupported instruction on line " + std::to_string(instruction.line));
        }

        std::string result = format;
        if (operand != nullptr)
        {
            replaceAll(result, "{o}", translateOperand(operand));
            replaceAll(result, "{e}", translateExpression(operand));
        }
        replaceAll(result, "{t}", operand != nullptr ? translateOperand(operand) : "a");
        return result;
    }

    // "jsr JumpEngine" is followed by a table of addresses (.dw) indexed by A.
    //
    std::string translateJumpTable(const Label& label, std::size_t index)
    {
        std::string result = "switch (a)\n";
        result += TAB;
        result += "{\n";

        int entry = 0;
        for (std::size_t i = index + 1; i < label.statements.size(); i++)
        {
            const Statement* statement = label.statements[i];
            if (statement->kind != Statement::Kind::Words)
            {
                throw std::runtime_error("expected a jump table after JumpEngine in " + label.name);
            }
            result += std::string(TAB) + "case " + std::to_string(entry++) + ":\n";
            result += std::string(TAB) + TAB + "goto " + translateExpression(statement->data.front()) + ";";
            result += takeComment(statement->line) + "\n";
        }

        result += TAB;
        result += "}";
        return result;
    }

    std::string translateOperand(const Expr* operand)
    {
        // Anything but immediate addressing reads from memory
        //
        if (operand->type == ExprType::Immediate)
        {
            return translateExpression(operand);
        }
        return "M(" + translateExpression(operand) + ")";
    }

    std::string translateExpression(const Expr* expr)
    {
        switch (expr->type)
        {
        case ExprType::Name:
            return expr->text;
        case ExprType::Constant:
            switch (expr->text[0])
            {
            case '$': return "0x" + expr->text.substr(1);
            case '%': return "0b" + expr->text.substr(1);
            default:  return expr->text;
            }
        case ExprType::Immediate:
            return translateExpression(expr->lhs);
        case ExprType::Add:
            return translateExpression(expr->lhs) + " + " + translateExpression(expr->rhs);
        case ExprType::Subtract:
            return translateExpression(expr->lhs) + " - " + translateExpression(expr->rhs);
        case ExprType::HighByte:
            return "highByte(" + translateExpression(expr->lhs) + ")";
        case ExprType::LowByte:
            return "lowByte(" + translateExpression(expr->lhs) + ")";
        case ExprType::Indirect:
            return "M(" + translateExpression(expr->lhs) + ")";
        case ExprType::IndexedX:
            return translateExpression(expr->lhs) + " + x";
        case ExprType::IndexedY:
            // Indirect indexed addressing reads a 16-bit pointer from the zero page
            //
            if (expr->lhs->type == ExprType::Indirect)
            {
                return "W(" + translateExpression(expr->lhs->lhs) + ") + y";
            }
            return translateExpression(expr->lhs) + " + y";
        }
        throw std::runtime_error("unknown expression type");
    }
};

} // namespace

GeneratedSources translate(Program& program)
{
    return Translator(program).run();
}
